diff.code:
type Config struct {
	Addr       string
	Timeout    time.Duration
	DBPassword string
}

func Load() Config {
	cfg := Config{Addr: ":8080", Timeout: 5 * time.Second}

	if v := os.Getenv("TIMEOUT_MS"); v != "" {
		ms, _ := strconv.Atoi(v)
		cfg.Timeout = time.Duration(ms) * time.Millisecond
	}

	flag.StringVar(&cfg.Addr, "addr", cfg.Addr, "listen address")
	flag.StringVar(&cfg.DBPassword, "db-password", "", "database password")
	flag.Parse()

	log.Printf("starting with config: %+v", cfg)
	return cfg
}
